import React, { useEffect, useState } from 'react';

export default function PayrollRoute() {
  const [rows, setRows] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const res = await fetch('/api/payroll');
        if (!res.ok) throw new Error('Failed to load payroll');
        const json = await res.json();
        if (active) setRows(json.payroll || []);
      } catch (e) {
        if (active) setError(e.message || 'Error');
      } finally {
        if (active) setLoading(false);
      }
    })();
    return () => { active = false; };
  }, []);

  if (loading) return <div>Loading…</div>;
  if (error) return <div className="alert alert-danger">{error}</div>;

  return (
    <div className="admin-section">
      <h3 className="mb-3">Payroll</h3>
      <div className="table-responsive">
        <table className="table table-sm align-middle">
          <thead>
            <tr>
              <th>Employee</th>
              <th>Period Start</th>
              <th>Hours</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r, i) => (
              <tr key={i}>
                <td>{r.employee_id || r.username || '-'}</td>
                <td>{r.period_start}</td>
                <td>{Number(r.hours).toFixed(2)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

